-- Fisiologia I 2026/27: organização curricular preservando IDs e histórico.
DROP TABLE IF EXISTS _fis_lessons_context; DROP TABLE IF EXISTS _fis_lesson_mapping;
CREATE TABLE _fis_lessons_context AS SELECT cu.id AS unit_id,(SELECT id FROM users ORDER BY (role='admin') DESC,created_at LIMIT 1) AS actor_id FROM curricular_units cu WHERE cu.code='FIS1';
CREATE TABLE _fis_lesson_mapping (suffix TEXT PRIMARY KEY,topic_id TEXT NOT NULL);
UPDATE question_bank_items SET topic_id=(SELECT topic_id FROM _fis_lesson_mapping m WHERE question_bank_items.id='compendium-question-fis1-'||m.suffix),updated_at=unixepoch()*1000 WHERE source_id='compendium-source-fis1' AND EXISTS (SELECT 1 FROM _fis_lesson_mapping m WHERE question_bank_items.id='compendium-question-fis1-'||m.suffix);
UPDATE quiz_questions SET topic_id=(SELECT topic_id FROM _fis_lesson_mapping m WHERE quiz_questions.id='compendium-quiz-fis1-'||m.suffix),updated_at=unixepoch()*1000 WHERE curricular_unit_id IN (SELECT unit_id FROM _fis_lessons_context) AND EXISTS (SELECT 1 FROM _fis_lesson_mapping m WHERE quiz_questions.id='compendium-quiz-fis1-'||m.suffix);
DROP TABLE _fis_lesson_mapping;
UPDATE quiz_topics SET status='archived',archived_at=unixepoch()*1000 WHERE curricular_unit_id IN (SELECT unit_id FROM _fis_lessons_context) AND id LIKE 'compendium-topic-fis1-%' AND NOT EXISTS (SELECT 1 FROM quiz_questions q WHERE q.topic_id=quiz_topics.id AND q.status='published' AND q.deleted_at IS NULL);
DROP TABLE _fis_lessons_context;
